def register(topic,q,detail):
    for title,symbol,why,principle,use,dt,body,qa,qb in ROWS:
        topic(title,'저장장치','block/blk-lib.c',symbol,why,principle,use,
              '바이트·512바이트 섹터·논리 블록 단위를 맞추고,마지막 미제출 BIO와 이미 제출된 BIO를 구별하세요.',
              q(title+' · '+qa[0],*qa[1:]),q(title+' · '+qb[0],*qb[1:]),
              details=[detail(dt,body),detail('검토 범위','Linux v6.12 block/blk-lib.c 전체와 bio.c의 연결·대기·참조 정리,관련 헤더 제한값을 대조했습니다. 소스 상태·계산 예제이며 실제 디스크 쓰기·삭제·고장 주입 시험을 수행하지 않았습니다.')])
